document.querySelector('#eraseData')?.addEventListener('click',()=>{if(!confirm('Je bewaarde kaarten uit deze browser wissen? Exporteer eerst een back-up als je die wilt behouden.'))return;const status=document.querySelector('#eraseStatus');try{localStorage.removeItem('kaartkompas-saved-v2');localStorage.removeItem('kaartkompas-saved');status.textContent='De lokale kaartverzameling is gewist. Sluit andere open Bindtopia-tabbladen om te voorkomen dat een oudere tab de verzameling opnieuw opslaat. Losse back-ups, foto’s en hostingcookies blijven bestaan.'}catch{status.textContent='Wissen lukte niet. Verwijder de sitegegevens via de instellingen van je browser.'}});
